// ─── File: SingleSupertypeDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.anon2;

import java.math.BigDecimal;
import java.util.logging.*;

public class SingleSupertypeDemo {
    private static final Logger log = Logger.getLogger(SingleSupertypeDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // CASE 1: anonymous class extends ONE class (BaseSettlementTask).
        // Because that class ALREADY implements Runnable, the anonymous object
        // is BOTH a BaseSettlementTask and a Runnable — but we only named ONE
        // supertype. Runnable came transitively, not from a second clause.
        BaseSettlementTask task = new BaseSettlementTask("TRD-1001", new BigDecimal("50000")) {
            @Override public void settle() {
                log.info(() -> "Settling " + getTradeId() + " amount Rs." + getAmount());
            }
        };
        boolean isRunnable = task instanceof Runnable;
        log.info(() -> "CASE1 anon is BaseSettlementTask AND Runnable? " + isRunnable);
        task.run(); // Runnable.run from base calls our settle()

        // CASE 2: we want BOTH Auditable and Comparable in a throwaway object.
        // We CANNOT write `new Auditable() implements Comparable {}`.
        // Correct way: a combined interface AuditableComparable extends both,
        // then implement that SINGLE interface anonymously.
        AuditableComparable entry = new AuditableComparable() {
            @Override public String auditTrail() { return "AUDIT: settlement TRD-1001"; }
            @Override public int compareTo(AuditableComparable o) { return 0; }
        };
        log.info(() -> "CASE2 anon implements combined interface: " + entry.auditTrail());

        // CASE 3: must EXTEND a concrete class AND implement a NEW interface at once.
        // Impossible anonymously → use a NAMED class.
        LedgerEntry le = new ExportableLedgerEntry("LED-1", new BigDecimal("50000"));
        log.info(() -> "CASE3 named class export: " + ((Exportable) le).exportLine());
    }
}

// ─── Would be in task/BaseSettlementTask.java ───
abstract class BaseSettlementTask implements Runnable {
    private final String tradeId;
    private final BigDecimal amount;
    BaseSettlementTask(String tradeId, BigDecimal amount) { this.tradeId = tradeId; this.amount = amount; }
    abstract void settle();
    @Override public void run() { settle(); }  // Runnable contract delegates to settle()
    String getTradeId() { return tradeId; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in contract/Auditable.java ───
interface Auditable { String auditTrail(); }

// ─── Would be in contract/AuditableComparable.java ───
// Interfaces CAN extend multiple interfaces. This single interface
// transitively requires both Auditable and Comparable method sets.
interface AuditableComparable extends Auditable, Comparable<AuditableComparable> { }

// ─── Would be in contract/Exportable.java ───
interface Exportable { String exportLine(); }

// ─── Would be in model/LedgerEntry.java ───
class LedgerEntry {
    private final String id;
    private final BigDecimal amount;
    LedgerEntry(String id, BigDecimal amount) { this.id = id; this.amount = amount; }
    String getId() { return id; }
    BigDecimal getAmount() { return amount; }
}

// ─── Would be in model/ExportableLedgerEntry.java ───
// NAMED class: extends ONE class AND implements ONE interface simultaneously.
// This is exactly what an anonymous class CANNOT do.
class ExportableLedgerEntry extends LedgerEntry implements Exportable {
    ExportableLedgerEntry(String id, BigDecimal amount) { super(id, amount); }
    @Override public String exportLine() { return getId() + "," + getAmount(); }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
